# JQL 예시: 나에게 할당된, 진행 중인 이슈 찾기
# project = MYPROJ AND assignee = currentUser() AND status = "In Progress"

# REST API로 새 이슈 생성
curl -X POST https://your-domain.atlassian.net/rest/api/3/issue \
  -H "Content-Type: application/json" \
  -H "Authorization: Basic <token>" \
  -d '{
    "fields": {
      "project": { "key": "MYPROJ" },
      "summary": "로그인 API 버그 수정",
      "description": "토큰 만료 시 500 에러 발생",
      "issuetype": { "name": "Bug" },
      "assignee": { "id": "123abc" }
    }
  }'
